const task = $input.first().json || {};
if (!task.role_task_id) return [];
const prompt = [
  'You are executing one Route B role task.',
  'role_id is supplied by public.route_b_role_task_queue.role_id.',
  'role_id: ' + task.role_id,
  'task_payload_json: ' + JSON.stringify(task.task_payload_json || {}),
  'context_refs_json: ' + JSON.stringify(task.context_refs_json || {}),
  'expected_output_schema_ref: ' + String(task.expected_output_schema_ref || ''),
  'Return strict JSON output only; no markdown; no code fences; no prose outside JSON.',
  'Treat this output as untrusted raw AI role output before deterministic validation.',
  'Do not call GitHub directly. For GitHub execution return structured github_execution_request_json only.',
  'Worker Poller must not call GitHub directly, must not merge, and must preserve PM_L2_ONLY merge authority.',
  'If role_id is PM_L3_DELIVERY_VALIDATION_OWNER, allowed decision_type values are create_next_role_task, request_github_execution_package, return_blocker, return_final_pm_l3_evidence_package, no_op.'
].join('\n');
return [{ json: { ...task, role_prompt: prompt, ollama_request: { model: 'gpt-oss:120b', stream: false, options: { temperature: 0.1 }, messages: [{ role: 'user', content: prompt }] } } }];

function hash16(input){let h1=0xdeadbeef^input.length;let h2=0x41c6ce57^input.length;for(let i=0;i<input.length;i++){const ch=input.charCodeAt(i);h1=Math.imul(h1^ch,2654435761);h2=Math.imul(h2^ch,1597334677);}h1=Math.imul(h1^(h1>>>16),2246822507)^Math.imul(h2^(h2>>>13),3266489909);h2=Math.imul(h2^(h2>>>16),2246822507)^Math.imul(h1^(h1>>>13),3266489909);return((h2>>>0).toString(16).padStart(8,'0')+(h1>>>0).toString(16).padStart(8,'0')).slice(0,16);}
function hash32(input){return hash16('a:'+input)+hash16('b:'+input);}
const task = $('Build Universal Role Prompt').item.json || {};
const response = $input.first().json || {};
const raw = response && response.message && typeof response.message.content === 'string' ? response.message.content : (typeof response.response === 'string' ? response.response : JSON.stringify(response));
let parsed = null; const errors = [];
try { parsed = JSON.parse(raw); } catch (error) { errors.push('ai_output_not_valid_json'); parsed = { untrusted_ai_output: raw }; }
const roleOutputId = 'role_output_' + hash32(task.role_task_id + ':' + String(task.expected_output_schema_ref || '') + ':' + raw);
return [{ json: { ...task, role_output_id: roleOutputId, raw_content: raw, raw_content_hash: hash32(raw), output_json: parsed, output_schema_ref: task.expected_output_schema_ref, validation_status: 'not_validated', validation_errors_json: errors } }];

const row = $('Build Raw Role Output Record').item.json || {};
const errors = Array.isArray(row.validation_errors_json) ? [...row.validation_errors_json] : [];
const output = row.output_json && typeof row.output_json === 'object' && !Array.isArray(row.output_json) ? row.output_json : {};
if (String(output.role_id || row.role_id) !== String(row.role_id)) errors.push('role_id_mismatch');
const text = JSON.stringify(output);
if (text.includes('```')) errors.push('markdown_code_fence_not_allowed');
if (text.includes('worker_poller_called_github') || text.includes('worker_poller_merged_pr')) errors.push('worker_poller_boundary_violation');
if (text.includes('pm_l2_approval_claimed') || text.includes('approved_for_merge')) errors.push('pm_l2_approval_claim_forbidden');
if (output.decision_type === 'request_github_execution_package' && !output.github_execution_request_json) errors.push('request_github_execution_package_requires_github_execution_request_json_structured_handoff');
let validation_status = 'pass';
if (errors.length > 0) validation_status = 'fail';
if (output.validation_status === 'conditional_pass') validation_status = 'conditional_pass';
if (output.validation_status === 'blocked') validation_status = 'blocked';
return [{ json: { ...row, output_json: output, validation_status, validation_errors_json: errors } }];
